const body = $json.body || $json || {};

const clean = (v) => String(v ?? '').trim();
const isUuid = (v) =>
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(clean(v));

const request_id = clean(body.request_id);
if (!isUuid(request_id)) {
  throw new Error('request_id debe ser un UUID válido y debe conservarse desde /api/eos.');
}

const usuario_id = clean(body.usuario_id || body.user_id || body.userId);
if (!isUuid(usuario_id)) {
  throw new Error('usuario_id debe ser un UUID válido de Supabase.');
}

const conversacion_id = clean(body.conversacion_id || body.conversation_id || body.conversationId);
if (!isUuid(conversacion_id)) {
  throw new Error('conversacion_id debe ser un UUID válido.');
}

const mensaje = clean(body.mensaje || body.message || body.text);
if (!mensaje) {
  throw new Error('mensaje es obligatorio.');
}

let archivo = null;
if (body.archivo && typeof body.archivo === 'object' && !Array.isArray(body.archivo)) {
  const nombre = clean(body.archivo.nombre);
  const tipo = clean(body.archivo.tipo);
  const base64 = clean(body.archivo.base64);
  const tamanio = Number(body.archivo.tamanio || 0) || 0;
  if (nombre && tipo && base64) archivo = { nombre, tipo, tamanio, base64 };
}

let archivo_categoria = '';
if (archivo) {
  if (archivo.tipo.startsWith('image/')) archivo_categoria = 'imagen';
  else if (archivo.tipo === 'application/pdf') archivo_categoria = 'pdf';
  else if (archivo.tipo.includes('word') || archivo.tipo.includes('officedocument.wordprocessingml')) archivo_categoria = 'word';
  else if (archivo.tipo.includes('excel') || archivo.tipo.includes('spreadsheet')) archivo_categoria = 'excel';
  else if (archivo.tipo === 'text/csv') archivo_categoria = 'csv';
  else if (archivo.tipo.startsWith('text/')) archivo_categoria = 'texto';
  else archivo_categoria = 'otro';
}

let imagen_data_url = '';
if (archivo && archivo_categoria === 'imagen') {
  imagen_data_url = archivo.base64.startsWith('data:')
    ? archivo.base64
    : `data:${archivo.tipo};base64,${archivo.base64}`;
}

return [{
  json: {
    request_id,
    usuario_id,
    usuario_id_original: usuario_id,
    usuario_key: usuario_id,
    conversacion_id,
    nombre: clean(body.nombre || body.name || body.usuario_nombre || 'Usuario'),
    mensaje,
    plan: clean(body.plan || 'free'),
    origen: clean(body.origen || 'eos-web'),
    historial: Array.isArray(body.historial) ? body.historial.slice(-10) : [],
    archivo,
    tiene_archivo: !!archivo,
    archivo_categoria,
    archivo_nombre: archivo?.nombre || '',
    archivo_tipo: archivo?.tipo || '',
    archivo_tamanio: archivo?.tamanio || 0,
    imagen_data_url,
    received_at: clean(body.received_at || new Date().toISOString())
  }
}];

const i = $('01 GW Preparar Entrada').first().json || {};

const historial = Array.isArray(i.historial)
  ? i.historial.slice(-10)
  : [];

const historialTexto = historial.length
  ? historial
      .map((h) => {
        const rol =
          String(h.rol || h.role || '').toLowerCase() === 'eos'
            ? 'EOS'
            : 'Usuario';

        const texto = String(
          h.texto ||
          h.mensaje ||
          h.content ||
          ''
        ).trim();

        return texto
          ? `${rol}: ${texto}`
          : '';
      })
      .filter(Boolean)
      .join('\n')
  : 'Sin historial previo.';

const tieneImagen =
  !!i.archivo &&
  i.archivo_categoria === 'imagen' &&
  !!i.imagen_data_url;

const prompt_eos = `
Usuario: ${i.nombre || 'Usuario'}
Plan: ${i.plan || 'free'}
Origen: ${i.origen || 'eos-web'}

Conversación reciente:
${historialTexto}

Mensaje actual:
${i.mensaje || ''}

${
  tieneImagen
    ? `El usuario adjuntó una imagen llamada "${i.archivo_nombre}". Analizá realmente el contenido visual de la imagen que acompaña este mensaje.`
    : ''
}
`.trim();

/*
  Contenido multimodal preparado para OpenAI.

  Si no hay imagen:
  [
    { type: "text", text: "..." }
  ]

  Si hay imagen:
  [
    { type: "text", text: "..." },
    {
      type: "image_url",
      image_url: {
        url: "data:image/png;base64,..."
      }
    }
  ]
*/

const contenido_openai = [
  {
    type: 'text',
    text: prompt_eos
  }
];

if (tieneImagen) {
  contenido_openai.push({
    type: 'image_url',
    image_url: {
      url: i.imagen_data_url
    }
  });
}

return [
  {
    json: {
      ...i,

      prompt_eos,

      tiene_imagen: tieneImagen,

      contenido_openai
    }
  }
];

const base =
  $('03 GW Construir Prompt Rápido').first().json || {};

const ai =
  $input.first().json || {};

/* =========================================================
   EXTRAER TEXTO DESDE RESPONSES API
========================================================= */

function extraerTexto(data) {
  if (
    data === null ||
    data === undefined
  ) {
    return '';
  }

  if (typeof data === 'string') {
    return data;
  }

  if (Array.isArray(data)) {
    for (const item of data) {
      const texto = extraerTexto(item);

      if (typeof texto === 'string' && texto.trim()) {
        return texto;
      }
    }

    return '';
  }

  if (typeof data === 'object') {

    /*
      Responses API:
      output -> message -> content -> output_text -> text
    */

    if (Array.isArray(data.output)) {
      for (const bloque of data.output) {

        if (
          bloque &&
          bloque.type === 'message' &&
          Array.isArray(bloque.content)
        ) {
          for (const parte of bloque.content) {

            if (
              parte &&
              parte.type === 'output_text' &&
              typeof parte.text === 'string'
            ) {
              return parte.text;
            }

          }
        }

      }
    }

    /*
      Compatibilidad con respuestas simplificadas
      o formatos alternativos.
    */

    if (
      typeof data.output_text === 'string'
    ) {
      return data.output_text;
    }

    if (
      typeof data.text === 'string'
    ) {
      return data.text;
    }

    if (
      typeof data.respuesta === 'string'
    ) {
      return data.respuesta;
    }

    if (
      typeof data.response === 'string'
    ) {
      return data.response;
    }

    if (
      typeof data.message === 'string'
    ) {
      return data.message;
    }

    if (data.content) {
      const textoContent =
        extraerTexto(data.content);

      if (textoContent) {
        return textoContent;
      }
    }
  }

  return '';
}

/* =========================================================
   TEXTO CRUDO DE OPENAI
========================================================= */

let raw =
  String(extraerTexto(ai) || '')
    .replace(/```json/gi, '')
    .replace(/```javascript/gi, '')
    .replace(/```js/gi, '')
    .replace(/```/g, '')
    .trim();

/* =========================================================
   PARSEAR JSON GENERADO POR EOS
========================================================= */

let resultado;

try {
  resultado = JSON.parse(raw);
} catch (error) {

  /*
    Si por algún motivo EOS responde texto normal,
    no rompemos el Gateway.
  */

  resultado = {
    respuesta:
      raw ||
      'Recibí tu mensaje, pero no pude interpretar correctamente la respuesta.',
    acciones: []
  };
}

/* =========================================================
   NORMALIZAR RESPUESTA
========================================================= */

const respuesta =
  typeof resultado?.respuesta === 'string' &&
  resultado.respuesta.trim()
    ? resultado.respuesta.trim()
    : 'Recibí tu solicitud.';

/* =========================================================
   ACCIONES PERMITIDAS
========================================================= */

const accionesPermitidas =
  new Set([
    'GENERAR_EXCEL',
    'GENERAR_PDF',
    'GENERAR_WORD',
    'CREAR_TAREA',
    'CREAR_OBJETIVO',
    'GUARDAR_MEMORIA',
    'VER_DASHBOARD',
    'VER_BRIEFING'
  ]);

/* =========================================================
   NORMALIZAR ACCIONES
========================================================= */

const acciones =
  Array.isArray(resultado?.acciones)
    ? resultado.acciones
        .map((accion) => {

          const tipo =
            String(
              accion?.tipo || ''
            )
              .trim()
              .toUpperCase();

          const datos =
            accion?.datos &&
            typeof accion.datos === 'object' &&
            !Array.isArray(accion.datos)
              ? accion.datos
              : {};

          return {
            tipo,
            datos
          };
        })
        .filter((accion) =>
          accionesPermitidas.has(
            accion.tipo
          )
        )
    : [];

/* =========================================================
   DETECTAR ARCHIVO / IMAGEN DE ENTRADA
========================================================= */

const tieneArchivo =
  !!base.archivo;

const archivoEntradaTipo =
  String(
    base.archivo_tipo ||
    base.archivo?.tipo ||
    ''
  ).trim();

const archivoEntradaNombre =
  String(
    base.archivo_nombre ||
    base.archivo?.nombre ||
    ''
  ).trim();

/* =========================================================
   SALIDA FINAL DEL GATEWAY
========================================================= */

/* =========================================================
   EL DOCUMENTO QUE EOS QUISO ARMAR

   Llega como campo del JSON del modelo. Acá solo se comprueba
   que tenga forma de documento: quien lo valida de verdad es
   `normalizarDocumento` del lado de la aplicación, que además
   recorta topes y descarta lo que no entiende.

   Si vino documento, se descartan las acciones de generar
   archivo: si no, el worker viejo armaría su plantilla
   genérica al mismo tiempo y el usuario recibiría dos
   archivos distintos por un solo pedido.
========================================================= */

const documento =
  resultado?.documento &&
  typeof resultado.documento === 'object' &&
  !Array.isArray(resultado.documento) &&
  typeof resultado.documento.titulo === 'string' &&
  Array.isArray(resultado.documento.bloques)
    ? resultado.documento
    : null;

const accionesDeArchivo = new Set([
  'GENERAR_EXCEL',
  'GENERAR_PDF',
  'GENERAR_WORD'
]);

const accionesFinales = documento
  ? acciones.filter(
      (a) => !accionesDeArchivo.has(a.tipo)
    )
  : acciones;

return [
  {
    json: {
      ...base,

      respuesta,

      documento,

      acciones: accionesFinales,

      requiere_worker:
        accionesFinales.length > 0,

      tipo: 'texto',

      accion_eos:
        accionesFinales.length > 0
          ? accionesFinales[0].tipo
          : 'RESPONDER',

      archivo_url: '',

      archivo_tipo: '',

      metadata: {
        plan:
          base.plan || 'free',

        origen:
          base.origen || 'eos-web',

        cantidad_acciones:
          accionesFinales.length,

        tiene_archivo:
          tieneArchivo,

        archivo_entrada_nombre:
          archivoEntradaNombre,

        archivo_entrada_tipo:
          archivoEntradaTipo,

        imagen_analizada:
          base.tiene_imagen === true,

        openai_response_id:
          ai.id || '',

        openai_status:
          ai.status || '',

        openai_model:
          ai.model || ''
      }
    }
  }
];

