const i = $('05 GW Preparar Respuesta').first().json || {};

const paths = {
  RESPONDER: 'eos-worker-rc1-respond',
  CREAR_TAREA: 'eos-worker-rc1-internal',
  CREAR_OBJETIVO: 'eos-worker-rc1-internal',
  GUARDAR_MEMORIA: 'eos-worker-rc1-internal',
  GENERAR_EXCEL: 'eos-worker-rc1-file',
  GENERAR_PDF: 'eos-worker-rc1-file',
  GENERAR_WORD: 'eos-worker-rc1-file',
  VER_DASHBOARD: 'eos-worker-rc1-dashboard',
  VER_BRIEFING: 'eos-worker-rc1-briefing'
};

const acciones =
  Array.isArray(i.acciones) && i.acciones.length
    ? i.acciones
    : [{ tipo: 'RESPONDER', datos: {} }];


/* =========================================================
   CONVERSACIÓN PURA

   Cuando el modelo no pide ninguna acción, arriba se fabrica
   un job RESPONDER solo para no romper el flujo.

   Ese job no produce ningún efecto durable: la rama RESPONDER
   del Worker únicamente hace un health ping y devuelve el mismo
   texto que ya tenemos acá, y el nodo 08 lo descarta igual.

   Marcamos el caso para poder saltear esa vuelta completa
   (0,7s a 5,6s medidos en producción) en el escenario más
   frecuente de todos.
========================================================= */

const sinAcciones =
  !Array.isArray(i.acciones) ||
  i.acciones.length === 0;


/* =========================================================
   HELPERS DETERMINÍSTICOS
========================================================= */

function texto(...valores) {
  for (const valor of valores) {
    if (
      typeof valor === 'string' &&
      valor.trim()
    ) {
      return valor.trim();
    }

    if (
      typeof valor === 'number' &&
      Number.isFinite(valor)
    ) {
      return String(valor);
    }
  }

  return '';
}


function prioridad(valor) {
  const n = Number(valor);

  if (!Number.isFinite(n)) {
    return 3;
  }

  return Math.max(
    1,
    Math.min(
      5,
      Math.round(n)
    )
  );
}


function importancia(valor) {
  const n = Number(valor);

  if (!Number.isFinite(n)) {
    return 5;
  }

  return Math.max(
    1,
    Math.min(
      10,
      Math.round(n)
    )
  );
}


/* =========================================================
   NORMALIZACIÓN CANÓNICA DE DATOS
========================================================= */

/*
  OBJETIVO:

  OpenAI puede expresar el mismo concepto usando
  diferentes nombres de campos.

  Ejemplo:

  nombre = titulo = name = asunto

  Para exact-once necesitamos convertir todos esos alias
  al MISMO contrato antes de enviar el payload al Worker.

  De esta manera el fingerprint durable depende de la
  intención real y no de pequeñas variaciones del modelo.
*/

function normalizarDatos(tipo, entrada) {
  const d =
    entrada &&
    typeof entrada === 'object' &&
    !Array.isArray(entrada)
      ? entrada
      : {};


  /* =======================================================
     CREAR_TAREA
  ======================================================= */

  if (tipo === 'CREAR_TAREA') {
    return {
      titulo: texto(
        d.titulo,
        d.nombre,
        d.name,
        d.asunto,
        d.tarea
      ),

      descripcion: texto(
        d.descripcion,
        d.description,
        d.detalle,
        d.detalles
      ),

      prioridad: prioridad(
        d.prioridad ??
        d.priority
      ),

      fecha_limite: texto(
        d.fecha_limite,
        d.fecha,
        d.deadline,
        d.due_date,
        d.vencimiento
      )
    };
  }


  /* =======================================================
     GUARDAR_MEMORIA
  ======================================================= */

  if (tipo === 'GUARDAR_MEMORIA') {
    return {
      titulo: texto(
        d.titulo,
        d.nombre,
        d.name
      ),

      categoria: texto(
        d.categoria,
        d.category
      ),

      contenido: texto(
        d.contenido,
        d.texto,
        d.descripcion,
        d.memoria,
        d.valor
      ),

      importancia: importancia(
        d.importancia ??
        d.importance
      )
    };
  }


  /* =======================================================
     ARCHIVOS
     GENERAR_EXCEL / GENERAR_PDF / GENERAR_WORD
  ======================================================= */

  if (
    tipo === 'GENERAR_EXCEL' ||
    tipo === 'GENERAR_PDF' ||
    tipo === 'GENERAR_WORD'
  ) {
    return {
      tema: texto(
        d.tema,
        d.asunto,
        d.objetivo,
        d.titulo,
        d.topic
      ),

      tipo: texto(
        d.tipo,
        d.type,
        d.plantilla,
        d.template
      ),

      rubro: texto(
        d.rubro,
        d.sector,
        d.categoria,
        d.industry
      ),

      negocio: texto(
        d.negocio,
        d.empresa,
        d.nombre_negocio,
        d.nombre_empresa,
        d.business,
        d.nombre
      ),

      descripcion: texto(
        d.descripcion,
        d.description,
        d.detalle,
        d.detalles
      )
    };
  }


  /* =======================================================
     CREAR_OBJETIVO

     Todavía conservamos los datos originales.
     Su contrato será validado independientemente.
  ======================================================= */

  if (tipo === 'CREAR_OBJETIVO') {
    return d;
  }


  /* =======================================================
     LECTURAS
  ======================================================= */

  if (
    tipo === 'VER_DASHBOARD' ||
    tipo === 'VER_BRIEFING'
  ) {
    return {};
  }


  /* =======================================================
     RESPONDER
  ======================================================= */

  if (tipo === 'RESPONDER') {
    return {};
  }


  /* =======================================================
     FALLBACK
  ======================================================= */

  return d;
}


/* =========================================================
   METADATA ESTABLE PARA EXACT-ONCE
========================================================= */

/*
  MUY IMPORTANTE:

  Nunca incluimos aquí información variable producida
  por una ejecución concreta de OpenAI como:

  - openai_response_id
  - openai_status
  - openai_model
  - timestamps de inferencia

  Esos datos pueden cambiar entre replays y causarían
  falsos EOS_COMMAND_PAYLOAD_MISMATCH.

  El payload durable debe representar la entrada y la
  intención del usuario.
*/

const metadataEstable = {
  plan: String(
    i.plan || 'free'
  ),

  origen: String(
    i.origen || 'eos-web'
  ),

  tiene_archivo:
    i.metadata?.tiene_archivo === true,

  archivo_entrada_nombre:
    String(
      i.metadata?.archivo_entrada_nombre ||
      ''
    ),

  archivo_entrada_tipo:
    String(
      i.metadata?.archivo_entrada_tipo ||
      ''
    ),

  imagen_analizada:
    i.metadata?.imagen_analizada === true
};


/* =========================================================
   CREAR JOBS PARA EL WORKER
========================================================= */

return acciones.map((accion, index) => {

  const tipo = String(
    accion?.tipo || 'RESPONDER'
  )
    .trim()
    .toUpperCase();


  /* =======================================================
     VALIDAR ACCIÓN
  ======================================================= */

  const worker_path =
    paths[tipo];

  if (!worker_path) {
    throw new Error(
      `Acción Worker no permitida: ${tipo}`
    );
  }


  /* =======================================================
     CANONICALIZAR DATOS
  ======================================================= */

  const datos =
    normalizarDatos(
      tipo,
      accion?.datos
    );


  /* =======================================================
     JOB FINAL
  ======================================================= */

  return {
    json: {

      /* ---------------------------------------------------
         IDENTIDAD DE REQUEST
      --------------------------------------------------- */

      request_id:
        i.request_id,

      usuario_id:
        i.usuario_id,

      usuario_id_original:
        i.usuario_id_original ||
        i.usuario_id,

      usuario_key:
        i.usuario_key ||
        i.usuario_id,

      conversacion_id:
        i.conversacion_id,


      /* ---------------------------------------------------
         CONTEXTO DEL USUARIO
      --------------------------------------------------- */

      nombre:
        i.nombre ||
        'Usuario',

      plan:
        i.plan ||
        'free',

      origen:
        i.origen ||
        'eos-web',


      /* ---------------------------------------------------
         ENTRADA ORIGINAL

         Debe mantenerse estable entre replays.
      --------------------------------------------------- */

      mensaje:
        i.mensaje ||
        '',


      /* ---------------------------------------------------
         RESPUESTA CONVERSACIONAL

         Puede variar entre llamadas a OpenAI.

         El Worker Gate no debe utilizar este campo
         como parte del fingerprint durable.
      --------------------------------------------------- */

      respuesta_gateway:
        i.respuesta ||
        '',


      /* ---------------------------------------------------
         ACCIÓN CANÓNICA
      --------------------------------------------------- */

      accion: {
        tipo,
        datos
      },


      /* ---------------------------------------------------
         CONTROL DE MÚLTIPLES ACCIONES
      --------------------------------------------------- */

      action_index:
        index,

      action_count:
        acciones.length,


      /* ---------------------------------------------------
         DESTINO DEL WORKER
      --------------------------------------------------- */

      worker_path,


      sin_acciones:
        sinAcciones,


      /* ---------------------------------------------------
         HISTORIAL

         Se conserva para contexto pero no debería
         formar parte del fingerprint durable del comando.
      --------------------------------------------------- */

      historial:
        Array.isArray(i.historial)
          ? i.historial
          : [],


      /* ---------------------------------------------------
         METADATA DETERMINÍSTICA
      --------------------------------------------------- */

      metadata:
        metadataEstable,


      /* ---------------------------------------------------
         OBSERVABILIDAD

         received_at puede servir para tracing,
         pero tampoco debe formar parte del fingerprint
         durable del Worker Gate.
      --------------------------------------------------- */

      received_at:
        i.received_at ||
        new Date().toISOString()
    }
  };
});

const base = $('05 GW Preparar Respuesta').first().json || {};
const resultados = $input.all().map((item) => item.json || {});

function esObjeto(valor) {
  return !!valor && typeof valor === 'object' && !Array.isArray(valor);
}

/*
  Extrae solamente texto real.
  Nunca convierte objetos mediante String(objeto),
  evitando "[object Object]".
*/
function extraerTexto(valor) {
  if (valor === null || valor === undefined) return '';

  if (typeof valor === 'string') {
    return valor.trim();
  }

  if (Array.isArray(valor)) {
    for (const item of valor) {
      const texto = extraerTexto(item);
      if (texto) return texto;
    }
    return '';
  }

  if (esObjeto(valor)) {
    const campos = [
      'respuesta',
      'message',
      'text',
      'output_text',
      'content'
    ];

    for (const campo of campos) {
      const texto = extraerTexto(valor[campo]);
      if (texto) return texto;
    }

    /*
      Algunos endpoints del Worker devuelven el resultado
      durable dentro de "resultado".
      Solo extraemos texto si realmente existe.
    */
    if (esObjeto(valor.resultado)) {
      for (const campo of campos) {
        const texto = extraerTexto(valor.resultado[campo]);
        if (texto) return texto;
      }
    }
  }

  return '';
}

function accionDe(resultado) {
  return String(
    resultado?.accion ||
    resultado?.action ||
    resultado?.resultado?.accion ||
    ''
  )
    .trim()
    .toUpperCase();
}

function tieneError(resultado) {
  return !!(
    resultado &&
    (
      resultado.ok === false ||
      resultado.error
    )
  );
}

const errores = resultados.filter(tieneError);
const validos = resultados.filter((r) => !tieneError(r));

/* =========================================================
   ARCHIVO GENERADO
========================================================= */

const archivo = validos.find(
  (r) =>
    typeof r.archivo_url === 'string' &&
    r.archivo_url.trim()
);

const archivoUrl = String(archivo?.archivo_url || '').trim();
const archivoTipo = String(archivo?.archivo_tipo || '').trim();
const archivoNombre = String(archivo?.archivo_nombre || '').trim();

/* =========================================================
   RESPUESTA BASE
========================================================= */

let respuesta =
  extraerTexto(base.respuesta) ||
  'Listo.';

/* =========================================================
   RESPUESTAS DEL WORKER
========================================================= */

const respuestasWorker = validos
  .filter((r) => accionDe(r) !== 'RESPONDER')
  .map((r) => extraerTexto(r))
  .filter(Boolean)
  .filter((text, index, arr) => arr.indexOf(text) === index)
  .filter((text) => !respuesta.includes(text));

/* =========================================================
   ACCIONES DE LECTURA
========================================================= */

const lectura = validos.find((r) => {
  const accion = accionDe(r);

  return (
    r.executed === true &&
    ['VER_DASHBOARD', 'VER_BRIEFING'].includes(accion) &&
    extraerTexto(r)
  );
});

if (lectura) {
  respuesta = extraerTexto(lectura);

  const extras = respuestasWorker.filter(
    (text) => text !== respuesta
  );

  if (extras.length) {
    respuesta =
      `${respuesta}\n\n${extras.join('\n\n')}`.trim();
  }
} else if (respuestasWorker.length) {
  respuesta =
    `${respuesta}\n\n${respuestasWorker.join('\n\n')}`.trim();
}

/* =========================================================
   ARCHIVO
========================================================= */

if (archivoUrl && !respuesta.includes(archivoUrl)) {
  respuesta =
    `${respuesta}\n\nDescargar archivo: ${archivoUrl}`.trim();
}

/* =========================================================
   ERRORES REALES
========================================================= */

if (errores.length) {
  const accionesConError = errores
    .map(accionDe)
    .filter(Boolean);

  if (accionesConError.length) {
    respuesta =
      `${respuesta}\n\nNo pude completar automáticamente: ${
        [...new Set(accionesConError)].join(', ')
      }.`.trim();
  }
}

/* =========================================================
   ACCIONES EJECUTADAS
========================================================= */

const accionesEjecutadas = validos
  .filter(
    (r) =>
      (
        r.executed === true ||
        r.estado === 'completada'
      ) &&
      r.idempotent !== true &&
      r.command_idempotent !== true &&
      r.decision !== 'completed'
  )
  .map(accionDe)
  .filter(Boolean);

/*
  Replays idempotentes se registran aparte.
  No los presentamos como una segunda ejecución.
*/
const accionesIdempotentes = validos
  .filter(
    (r) =>
      r.idempotent === true ||
      r.command_idempotent === true ||
      r.decision === 'completed'
  )
  .map(accionDe)
  .filter(Boolean);

/* =========================================================
   SALIDA FINAL
========================================================= */

/* =========================================================
   SOLO LO QUE LA APLICACIÓN USA

   Antes se esparcía `...base`, que arrastra todo el estado
   interno del workflow: el prompt armado, lo que se le mandó
   a OpenAI, el historial y —si el usuario adjuntó una foto—
   `imagen_data_url` con el base64 completo.

   Subir una imagen de 8 MB hacía que esos 8 MB volvieran de
   n8n a Vercel para ser descartados ahí mismo.

   Esta lista es exactamente lo que lee `normalizarRespuestaN8N`
   en app/api/eos/route.ts. Si algún día hace falta un campo
   más, se agrega acá y no se vuelve a abrir la canilla.
========================================================= */

return [
  {
    json: {
      request_id: base.request_id,
      conversacion_id: base.conversacion_id,

      respuesta,

      documento: base.documento ?? null,

      acciones: base.acciones || [],

      tipo: archivoUrl
        ? 'archivo'
        : 'texto',

      archivo_url: archivoUrl,
      archivo_tipo: archivoTipo,
      archivo_nombre: archivoNombre,

      accion: archivo
        ? accionDe(archivo) || 'GENERAR_EXCEL'
        : String(base.accion_eos || 'RESPONDER'),

      metadata: base.metadata || {},

      worker: {
        ok: errores.length === 0,

        resultados: resultados.length,

        acciones_ejecutadas: [
          ...new Set(accionesEjecutadas)
        ],

        acciones_idempotentes: [
          ...new Set(accionesIdempotentes)
        ],

        errores: errores.map((e) => ({
          accion: accionDe(e),
          error:
            extraerTexto(e.error) ||
            extraerTexto(e.message) ||
            'Worker no completado'
        }))
      }
    }
  }
];

const entrada = $('01 GW Preparar Entrada').first().json || {};
const rows = $input.all().map((item) => item.json || {}).filter((row) => row && Object.keys(row).length);

const reserva = rows.find((row) =>
  String(row.usuario_id || '') === entrada.usuario_id &&
  String(row.request_id || '') === entrada.request_id &&
  String(row.status || '') === 'reserved'
);

const expira = reserva?.expires_at ? new Date(reserva.expires_at).getTime() : 0;
const source = reserva?.metadata && typeof reserva.metadata === 'object'
  ? String(reserva.metadata.source || '')
  : '';

if (!reserva || !Number.isFinite(expira) || expira <= Date.now() || source !== 'api-eos-v40') {
  throw new Error('Gateway RC1 bloqueó un request sin reserva server-owned válida.');
}

return [{
  json: {
    ...entrada,
    gateway_admission: {
      ok: true,
      reservation_id: reserva.id || null,
      expires_at: reserva.expires_at,
      source
    }
  }
}];

/*
  Conversación pura: el modelo no pidió ninguna acción.

  Devolvemos exactamente la misma forma que devolvía la rama
  RESPONDER del Background Worker, para que el nodo 08 se
  comporte igual que siempre — pero sin la vuelta completa
  (n8n -> worker -> Vercel health ping -> vuelta) que solo
  servía para que su resultado terminara descartado.
*/

const base = $('05 GW Preparar Respuesta').first().json || {};
const job = $input.first().json || {};

return [{
  json: {
    ok: true,
    executed: false,
    request_id: job.request_id,
    accion: 'RESPONDER',
    respuesta: base.respuesta || '',
    tipo: 'texto'
  }
}];
